package io.github.charlietap.chasm.executor.invoker.dispatch.aggregate

import io.github.charlietap.chasm.runtime.dispatch.DispatchableInstruction
import io.github.charlietap.chasm.runtime.instruction.AggregateInstruction

fun AggregateInstructionDispatcher(
    instruction: AggregateInstruction,
): DispatchableInstruction = when (instruction) {
    is AggregateInstruction.ArrayCopyIii -> ArrayCopyIiiDispatcher(instruction.elementsToCopy, instruction.sourceOffset, instruction.destinationOffset, instruction.sourceAddressSlot, instruction.destinationAddressSlot)
    is AggregateInstruction.ArrayCopyIis -> ArrayCopyIisDispatcher(instruction.elementsToCopy, instruction.sourceOffset, instruction.destinationOffsetSlot, instruction.sourceAddressSlot, instruction.destinationAddressSlot)
    is AggregateInstruction.ArrayCopyIsi -> ArrayCopyIsiDispatcher(instruction.elementsToCopy, instruction.sourceOffsetSlot, instruction.destinationOffset, instruction.sourceAddressSlot, instruction.destinationAddressSlot)
    is AggregateInstruction.ArrayCopyIss -> ArrayCopyIssDispatcher(instruction.elementsToCopy, instruction.sourceOffsetSlot, instruction.destinationOffsetSlot, instruction.sourceAddressSlot, instruction.destinationAddressSlot)
    is AggregateInstruction.ArrayCopySii -> ArrayCopySiiDispatcher(instruction.elementsToCopySlot, instruction.sourceOffset, instruction.destinationOffset, instruction.sourceAddressSlot, instruction.destinationAddressSlot)
    is AggregateInstruction.ArrayCopySis -> ArrayCopySisDispatcher(instruction.elementsToCopySlot, instruction.sourceOffset, instruction.destinationOffsetSlot, instruction.sourceAddressSlot, instruction.destinationAddressSlot)
    is AggregateInstruction.ArrayCopySsi -> ArrayCopySsiDispatcher(instruction.elementsToCopySlot, instruction.sourceOffsetSlot, instruction.destinationOffset, instruction.sourceAddressSlot, instruction.destinationAddressSlot)
    is AggregateInstruction.ArrayCopySss -> ArrayCopySssDispatcher(instruction.elementsToCopySlot, instruction.sourceOffsetSlot, instruction.destinationOffsetSlot, instruction.sourceAddressSlot, instruction.destinationAddressSlot)
    is AggregateInstruction.ArrayFillIii -> ArrayFillIiiDispatcher(instruction.elementsToFill, instruction.fillValue, instruction.arrayElementOffset, instruction.addressSlot)
    is AggregateInstruction.ArrayFillIis -> ArrayFillIisDispatcher(instruction.elementsToFill, instruction.fillValue, instruction.arrayElementOffsetSlot, instruction.addressSlot)
    is AggregateInstruction.ArrayFillIsi -> ArrayFillIsiDispatcher(instruction.elementsToFill, instruction.fillValueSlot, instruction.arrayElementOffset, instruction.addressSlot)
    is AggregateInstruction.ArrayFillIss -> ArrayFillIssDispatcher(instruction.elementsToFill, instruction.fillValueSlot, instruction.arrayElementOffsetSlot, instruction.addressSlot)
    is AggregateInstruction.ArrayFillSii -> ArrayFillSiiDispatcher(instruction.elementsToFillSlot, instruction.fillValue, instruction.arrayElementOffset, instruction.addressSlot)
    is AggregateInstruction.ArrayFillSis -> ArrayFillSisDispatcher(instruction.elementsToFillSlot, instruction.fillValue, instruction.arrayElementOffsetSlot, instruction.addressSlot)
    is AggregateInstruction.ArrayFillSsi -> ArrayFillSsiDispatcher(instruction.elementsToFillSlot, instruction.fillValueSlot, instruction.arrayElementOffset, instruction.addressSlot)
    is AggregateInstruction.ArrayFillSss -> ArrayFillSssDispatcher(instruction.elementsToFillSlot, instruction.fillValueSlot, instruction.arrayElementOffsetSlot, instruction.addressSlot)
    is AggregateInstruction.ArrayGetI -> ArrayGetIDispatcher(instruction.addressSlot, instruction.field, instruction.destinationSlot)
    is AggregateInstruction.ArrayGetS -> ArrayGetSDispatcher(instruction.addressSlot, instruction.fieldSlot, instruction.destinationSlot)
    is AggregateInstruction.ArrayGetSignedI -> ArrayGetSignedIDispatcher(instruction.addressSlot, instruction.field, instruction.destinationSlot, instruction.packedType)
    is AggregateInstruction.ArrayGetSignedS -> ArrayGetSignedSDispatcher(instruction.addressSlot, instruction.fieldSlot, instruction.destinationSlot, instruction.packedType)
    is AggregateInstruction.ArrayGetUnsignedI -> ArrayGetUnsignedIDispatcher(instruction.addressSlot, instruction.field, instruction.destinationSlot, instruction.packedType)
    is AggregateInstruction.ArrayGetUnsignedS -> ArrayGetUnsignedSDispatcher(instruction.addressSlot, instruction.fieldSlot, instruction.destinationSlot, instruction.packedType)
    is AggregateInstruction.ArrayLenS -> ArrayLenSDispatcher(instruction.addressSlot, instruction.destinationSlot)
    is AggregateInstruction.ArrayNewIi -> ArrayNewIiDispatcher(instruction.size, instruction.value, instruction.destinationSlot, instruction.rtt)
    is AggregateInstruction.ArrayNewIs -> ArrayNewIsDispatcher(instruction.size, instruction.valueSlot, instruction.destinationSlot, instruction.rtt)
    is AggregateInstruction.ArrayNewSi -> ArrayNewSiDispatcher(instruction.sizeSlot, instruction.value, instruction.destinationSlot, instruction.rtt)
    is AggregateInstruction.ArrayNewSs -> ArrayNewSsDispatcher(instruction.sizeSlot, instruction.valueSlot, instruction.destinationSlot, instruction.rtt)
    is AggregateInstruction.ArrayNewDefaultI -> ArrayNewDefaultIDispatcher(instruction.size, instruction.destinationSlot, instruction.rtt, instruction.field)
    is AggregateInstruction.ArrayNewDefaultS -> ArrayNewDefaultSDispatcher(instruction.sizeSlot, instruction.destinationSlot, instruction.rtt, instruction.field)
    is AggregateInstruction.ArrayNewDataIi -> ArrayNewDataIiDispatcher(instruction.sourceOffset, instruction.arrayLength, instruction.destinationSlot, instruction.rtt, instruction.dataInstance, instruction.fieldWidthInBytes)
    is AggregateInstruction.ArrayNewDataIs -> ArrayNewDataIsDispatcher(instruction.sourceOffset, instruction.arrayLengthSlot, instruction.destinationSlot, instruction.rtt, instruction.dataInstance, instruction.fieldWidthInBytes)
    is AggregateInstruction.ArrayNewDataSi -> ArrayNewDataSiDispatcher(instruction.sourceOffsetSlot, instruction.arrayLength, instruction.destinationSlot, instruction.rtt, instruction.dataInstance, instruction.fieldWidthInBytes)
    is AggregateInstruction.ArrayNewDataSs -> ArrayNewDataSsDispatcher(instruction.sourceOffsetSlot, instruction.arrayLengthSlot, instruction.destinationSlot, instruction.rtt, instruction.dataInstance, instruction.fieldWidthInBytes)
    is AggregateInstruction.ArrayNewElementIi -> ArrayNewElementIiDispatcher(instruction.sourceOffset, instruction.arrayLength, instruction.destinationSlot, instruction.rtt, instruction.elementInstance)
    is AggregateInstruction.ArrayNewElementIs -> ArrayNewElementIsDispatcher(instruction.sourceOffset, instruction.arrayLengthSlot, instruction.destinationSlot, instruction.rtt, instruction.elementInstance)
    is AggregateInstruction.ArrayNewElementSi -> ArrayNewElementSiDispatcher(instruction.sourceOffsetSlot, instruction.arrayLength, instruction.destinationSlot, instruction.rtt, instruction.elementInstance)
    is AggregateInstruction.ArrayNewElementSs -> ArrayNewElementSsDispatcher(instruction.sourceOffsetSlot, instruction.arrayLengthSlot, instruction.destinationSlot, instruction.rtt, instruction.elementInstance)
    is AggregateInstruction.ArrayNewFixedS -> ArrayNewFixedSDispatcher(instruction.firstElementSlot, instruction.destinationSlot, instruction.rtt, instruction.size)
    is AggregateInstruction.ArraySetIi -> ArraySetIiDispatcher(instruction.value, instruction.field, instruction.addressSlot)
    is AggregateInstruction.ArraySetIs -> ArraySetIsDispatcher(instruction.value, instruction.fieldSlot, instruction.addressSlot)
    is AggregateInstruction.ArraySetSi -> ArraySetSiDispatcher(instruction.valueSlot, instruction.field, instruction.addressSlot)
    is AggregateInstruction.ArraySetSs -> ArraySetSsDispatcher(instruction.valueSlot, instruction.fieldSlot, instruction.addressSlot)
    is AggregateInstruction.ArrayInitDataIii -> ArrayInitDataIiiDispatcher(instruction.elementsToCopy, instruction.sourceOffset, instruction.destinationOffset, instruction.addressSlot, instruction.dataInstance, instruction.fieldWidthInBytes)
    is AggregateInstruction.ArrayInitDataIis -> ArrayInitDataIisDispatcher(instruction.elementsToCopy, instruction.sourceOffset, instruction.destinationOffsetSlot, instruction.addressSlot, instruction.dataInstance, instruction.fieldWidthInBytes)
    is AggregateInstruction.ArrayInitDataIsi -> ArrayInitDataIsiDispatcher(instruction.elementsToCopy, instruction.sourceOffsetSlot, instruction.destinationOffset, instruction.addressSlot, instruction.dataInstance, instruction.fieldWidthInBytes)
    is AggregateInstruction.ArrayInitDataIss -> ArrayInitDataIssDispatcher(instruction.elementsToCopy, instruction.sourceOffsetSlot, instruction.destinationOffsetSlot, instruction.addressSlot, instruction.dataInstance, instruction.fieldWidthInBytes)
    is AggregateInstruction.ArrayInitDataSii -> ArrayInitDataSiiDispatcher(instruction.elementsToCopySlot, instruction.sourceOffset, instruction.destinationOffset, instruction.addressSlot, instruction.dataInstance, instruction.fieldWidthInBytes)
    is AggregateInstruction.ArrayInitDataSis -> ArrayInitDataSisDispatcher(instruction.elementsToCopySlot, instruction.sourceOffset, instruction.destinationOffsetSlot, instruction.addressSlot, instruction.dataInstance, instruction.fieldWidthInBytes)
    is AggregateInstruction.ArrayInitDataSsi -> ArrayInitDataSsiDispatcher(instruction.elementsToCopySlot, instruction.sourceOffsetSlot, instruction.destinationOffset, instruction.addressSlot, instruction.dataInstance, instruction.fieldWidthInBytes)
    is AggregateInstruction.ArrayInitDataSss -> ArrayInitDataSssDispatcher(instruction.elementsToCopySlot, instruction.sourceOffsetSlot, instruction.destinationOffsetSlot, instruction.addressSlot, instruction.dataInstance, instruction.fieldWidthInBytes)
    is AggregateInstruction.ArrayInitElementIii -> ArrayInitElementIiiDispatcher(instruction.elementsToCopy, instruction.sourceOffset, instruction.destinationOffset, instruction.addressSlot, instruction.elementInstance)
    is AggregateInstruction.ArrayInitElementIis -> ArrayInitElementIisDispatcher(instruction.elementsToCopy, instruction.sourceOffset, instruction.destinationOffsetSlot, instruction.addressSlot, instruction.elementInstance)
    is AggregateInstruction.ArrayInitElementIsi -> ArrayInitElementIsiDispatcher(instruction.elementsToCopy, instruction.sourceOffsetSlot, instruction.destinationOffset, instruction.addressSlot, instruction.elementInstance)
    is AggregateInstruction.ArrayInitElementIss -> ArrayInitElementIssDispatcher(instruction.elementsToCopy, instruction.sourceOffsetSlot, instruction.destinationOffsetSlot, instruction.addressSlot, instruction.elementInstance)
    is AggregateInstruction.ArrayInitElementSii -> ArrayInitElementSiiDispatcher(instruction.elementsToCopySlot, instruction.sourceOffset, instruction.destinationOffset, instruction.addressSlot, instruction.elementInstance)
    is AggregateInstruction.ArrayInitElementSis -> ArrayInitElementSisDispatcher(instruction.elementsToCopySlot, instruction.sourceOffset, instruction.destinationOffsetSlot, instruction.addressSlot, instruction.elementInstance)
    is AggregateInstruction.ArrayInitElementSsi -> ArrayInitElementSsiDispatcher(instruction.elementsToCopySlot, instruction.sourceOffsetSlot, instruction.destinationOffset, instruction.addressSlot, instruction.elementInstance)
    is AggregateInstruction.ArrayInitElementSss -> ArrayInitElementSssDispatcher(instruction.elementsToCopySlot, instruction.sourceOffsetSlot, instruction.destinationOffsetSlot, instruction.addressSlot, instruction.elementInstance)
    is AggregateInstruction.RefI31I -> RefI31IDispatcher(instruction.value, instruction.destinationSlot)
    is AggregateInstruction.RefI31S -> RefI31SDispatcher(instruction.valueSlot, instruction.destinationSlot)
    is AggregateInstruction.I31GetSignedS -> I31GetSignedSDispatcher(instruction.valueSlot, instruction.destinationSlot)
    is AggregateInstruction.I31GetUnsignedS -> I31GetUnsignedSDispatcher(instruction.valueSlot, instruction.destinationSlot)
    is AggregateInstruction.AnyConvertExternS -> AnyConvertExternSDispatcher(instruction.valueSlot, instruction.destinationSlot)
    is AggregateInstruction.ExternConvertAnyS -> ExternConvertAnySDispatcher(instruction.valueSlot, instruction.destinationSlot)
    is AggregateInstruction.StructGetS -> StructGetSDispatcher(instruction.addressSlot, instruction.destinationSlot, instruction.fieldIndex)
    is AggregateInstruction.StructGetSignedS -> StructGetSignedSDispatcher(instruction.addressSlot, instruction.destinationSlot, instruction.fieldIndex, instruction.packedType)
    is AggregateInstruction.StructGetUnsignedS -> StructGetUnsignedSDispatcher(instruction.addressSlot, instruction.destinationSlot, instruction.fieldIndex, instruction.packedType)
    is AggregateInstruction.RefCastStructGetS -> RefCastStructGetSDispatcher(instruction.referenceSlot, instruction.destinationSlot, instruction.typeTest, instruction.fieldIndex)
    is AggregateInstruction.StructGetStructGetS -> StructGetStructGetSDispatcher(instruction.addressSlot, instruction.destinationSlot, instruction.firstFieldIndex, instruction.secondFieldIndex)
    is AggregateInstruction.LocalSetStructGetS -> LocalSetStructGetSDispatcher(instruction.sourceSlot, instruction.localSlot, instruction.destinationSlot, instruction.fieldIndex)
    is AggregateInstruction.StructNewS -> StructNewSDispatcher(instruction.firstFieldSlot, instruction.destinationSlot, instruction.rtt)
    is AggregateInstruction.StructNewDefaultS -> StructNewDefaultSDispatcher(instruction.destinationSlot, instruction.rtt, instruction.fields)
    is AggregateInstruction.StructSetI -> StructSetIDispatcher(instruction.value, instruction.addressSlot, instruction.fieldIndex)
    is AggregateInstruction.StructSetS -> StructSetSDispatcher(instruction.valueSlot, instruction.addressSlot, instruction.fieldIndex)
}
